   168          if(!dst->references) {
   169              UA_Node_deleteMembers(dst);
   170              return UA_STATUSCODE_BADOUTOFMEMORY;
   171          }
   172          dst->referencesSize = src->referencesSize;
   173
   174          for(size_t i = 0; i < src->referencesSize; ++i) {
   175              UA_NodeReferenceKind *srefs = &src->references[i];
   176              UA_NodeReferenceKind *drefs = &dst->references[i];
   177              drefs->isInverse = srefs->isInverse;
   178              retval = UA_NodeId_copy(&srefs->referenceTypeId, &drefs->referenceTypeId);
   179              if(retval != UA_STATUSCODE_GOOD)
   180                  break;
   181              retval = UA_Array_copy(srefs->targetIds, srefs->targetIdsSize,
   182                                      (void**)&drefs->targetIds,
   183                                      &UA_TYPES[UA_TYPES_EXPANDEDNODEID]);
   184              if(retval != UA_STATUSCODE_GOOD)
   185                  break;
   186              drefs->targetIdsSize = srefs->targetIdsSize;
   187          }
   188          if(retval != UA_STATUSCODE_GOOD) {
   189              UA_Node_deleteMembers(dst);
   190              return retval;
   191          }
   192      }
   193
   194      /* Copy unique content of the nodeclass */
   195      switch(src->nodeClass) {
   196      case UA_NODECLASS_OBJECT:
   197          retval = UA_ObjectNode_copy((const UA_ObjectNode*)src, (UA_ObjectNode*)dst);
   198          break;
   199      case UA_NODECLASS_VARIABLE:
   200          retval = UA_VariableNode_copy((const UA_VariableNode*)src, (UA_VariableNode*)dst);
   201          break;
   202      case UA_NODECLASS_METHOD:
   203          retval = UA_MethodNode_copy((const UA_MethodNode*)src, (UA_MethodNode*)dst);
   204          break;
   205      case UA_NODECLASS_OBJECTTYPE:
   206          retval = UA_ObjectTypeNode_copy((const UA_ObjectTypeNode*)src, (UA_ObjectTypeNode*)dst);
   207          break;
   208      case UA_NODECLASS_VARIABLETYPE:
   209          retval = UA_VariableTypeNode_copy((const UA_VariableTypeNode*)src, (UA_VariableTypeNode*)dst);
   210          break;
   211      case UA_NODECLASS_REFERENCETYPE:
   212          retval = UA_ReferenceTypeNode_copy((const UA_ReferenceTypeNode*)src, (UA_ReferenceTypeNode*)dst);
   213          break;
   214      case UA_NODECLASS_DATATYPE:
   215          retval = UA_DataTypeNode_copy((const UA_DataTypeNode*)src, (UA_DataTypeNode*)dst);
   216          break;
   217      case UA_NODECLASS_VIEW:
   218          retval = UA_ViewNode_copy((const UA_ViewNode*)src, (UA_ViewNode*)dst);
   219          break;
   220      default:
   221          break;
   222      }
   223
   224      if(retval != UA_STATUSCODE_GOOD)
   225          UA_Node_deleteMembers(dst);
   226
   227      return retval;
   228  }
